"""
Screen 6 — Apply configuration.

Runs all apply steps in a background GLib thread.
Each step reports back to the main thread via GLib.idle_add(),
updating a live progress row in the UI.
"""

import gi
gi.require_version("Gtk", "4.0")
gi.require_version("Adw", "1")

from gi.repository import Gtk, Adw, GLib

from .base import BasePage
from ..state import WizardState
from ..backend.apply import run_apply, STEPS
from typing import Callable
import subprocess
import os


# Map step_id → display label
STEP_LABELS = {s[0]: s[1] for s in STEPS}


class ApplyScreen(BasePage):
    def __init__(self, state: WizardState, go_to: Callable):
        super().__init__(state, go_to, title="Applying", tag="apply")

    def _build(self):
        self._body.append(
            self.make_page_header(
                "Applying configuration",
                "BulwarkOS is configuring your isolation stack. "
                "Do not power off your system.",
            )
        )

        # Progress rows group
        self._steps_group = Adw.PreferencesGroup()
        self._steps_group.set_title("Progress")
        self._body.append(self._steps_group)

        # Build one row per step
        self._step_rows: dict[str, tuple[Adw.ActionRow, Gtk.Label]] = {}
        for step_id, label, _fn in STEPS:
            row = Adw.ActionRow()
            row.set_title(label)

            status_lbl = Gtk.Label(label="Pending")
            status_lbl.add_css_class("dim-label")
            row.add_suffix(status_lbl)

            spinner = Gtk.Spinner()
            spinner.set_size_request(16, 16)
            spinner.set_visible(False)
            row.add_suffix(spinner)

            self._step_rows[step_id] = (row, status_lbl, spinner)
            self._steps_group.add(row)

        # Error expander — shown if any step fails
        self._error_expander = Adw.ExpanderRow()
        self._error_expander.set_title("Errors — expand to view details")
        self._error_expander.set_visible(False)
        self._steps_group.add(self._error_expander)

        # Success banner
        self._done_banner = Adw.Banner()
        self._done_banner.set_title(
            "Setup complete! BulwarkOS will reboot to activate your configuration."
        )
        self._done_banner.set_revealed(False)
        self._body.append(self._done_banner)

        # Reboot button row — hidden until done
        self._reboot_row = Gtk.Box(orientation=Gtk.Orientation.HORIZONTAL, spacing=12)
        self._reboot_row.set_margin_top(8)
        self._reboot_row.set_visible(False)

        spacer = Gtk.Box()
        spacer.set_hexpand(True)
        self._reboot_row.append(spacer)

        self._reboot_btn = Gtk.Button(label="Reboot Now")
        self._reboot_btn.add_css_class("suggested-action")
        self._reboot_btn.connect("clicked", self._on_reboot)
        self._reboot_row.append(self._reboot_btn)

        self._body.append(self._reboot_row)

    def on_enter(self):
        """Start the apply thread when this screen is first entered."""
        # Reset all rows
        for step_id, (row, lbl, spinner) in self._step_rows.items():
            lbl.set_label("Pending")
            lbl.set_css_classes(["dim-label"])
            spinner.stop()
            spinner.set_visible(False)

        self._done_banner.set_revealed(False)
        self._reboot_row.set_visible(False)
        self._error_expander.set_visible(False)

        # Run in background thread
        GLib.Thread.new("apply", self._apply_thread, None)

    def _apply_thread(self, _data):
        """Background thread — calls run_apply which calls on_step for each step."""
        all_ok = run_apply(self.state, self._on_step_callback)
        GLib.idle_add(self._on_all_done, all_ok)

    def _on_step_callback(self, step_id: str, message: str, success):
        """
        Called by run_apply for each step update.
        success=None means in-progress; True/False means done.
        This is called from the background thread, so we must schedule
        UI updates via GLib.idle_add.
        """
        GLib.idle_add(self._update_step_ui, step_id, message, success)

    def _update_step_ui(self, step_id: str, message: str, success):
        """GTK main thread — updates the status row for a step."""
        if step_id not in self._step_rows:
            return GLib.SOURCE_REMOVE

        row, lbl, spinner = self._step_rows[step_id]

        if success is None:
            # In progress
            lbl.set_label("Running…")
            lbl.set_css_classes(["dim-label"])
            spinner.set_visible(True)
            spinner.start()
        elif success:
            lbl.set_label("Done")
            lbl.set_css_classes(["success"])
            spinner.stop()
            spinner.set_visible(False)
        else:
            lbl.set_label("Failed")
            lbl.set_css_classes(["error"])
            spinner.stop()
            spinner.set_visible(False)
            # Add error detail to expander
            err_row = Adw.ActionRow()
            err_row.set_title(STEP_LABELS.get(step_id, step_id))
            err_row.set_subtitle(message[:200])  # truncate very long messages
            self._error_expander.add_row(err_row)
            self._error_expander.set_visible(True)

        return GLib.SOURCE_REMOVE

    def _on_all_done(self, all_ok: bool):
        """Called on the GTK main thread when all steps have finished."""
        self._done_banner.set_revealed(True)

        if not all_ok:
            self._done_banner.set_title(
                "Setup completed with errors. Review the error details above. "
                "You may still reboot — some settings may not be active."
            )

        self._reboot_row.set_visible(True)
        return GLib.SOURCE_REMOVE

    def _on_reboot(self, _btn):
        """Trigger a systemd reboot."""
        try:
            subprocess.run(
                ["pkexec", "systemctl", "reboot"],
                check=True,
                timeout=10,
            )
        except Exception as e:
            dialog = Adw.MessageDialog(
                transient_for=self.get_root(),
                heading="Reboot failed",
                body=f"Could not reboot automatically:\n{e}\n\nPlease reboot manually.",
            )
            dialog.add_response("ok", "OK")
            dialog.present()
